char* hash_certificate(const char *cert) {
    // BEGIN SOLUTION
    unsigned char hash[MD5_DIGEST_LENGTH];
    char *hex_string = malloc(MD5_DIGEST_LENGTH * 2 + 1); // 2 characters per byte + null terminator
